options.getOption:
const series = context.panel.data.series[0];
const fields = {};
(series ? series.fields : []).forEach((f) => {
  fields[f.name] = f.values && f.values.toArray ? f.values.toArray() : (f.values || []);
});
const n = (fields.From_Lon || []).length;
const normal = [];
const cut = [];
const highPressure = [];
const modPressure = [];
const newRoute = [];
for (let i = 0; i < n; i++) {
  const item = { coords: [[fields.From_Lon[i], fields.From_Lat[i]], [fields.To_Lon[i], fields.To_Lat[i]]] };
  const p = fields.Pressure ? fields.Pressure[i] : null;
  if (fields.Cut[i]) {
    cut.push(item);
  } else if (p === null || p === undefined) {
    normal.push(item);
  } else if (p === -1) {
    newRoute.push(item);
  } else if (p >= 3) {
    highPressure.push(item);
  } else {
    modPressure.push(item);
  }
}

const option = {
  backgroundColor: 'transparent',
  globe: {
    baseTexture: 'https://raw.githubusercontent.com/nluecke/fork-the-internet/main/assets/world.topo.bathy.200401.jpg',
    heightTexture: 'https://raw.githubusercontent.com/nluecke/fork-the-internet/main/assets/world.topo.bathy.200401.jpg',
    shading: 'lambert',
    light: { ambient: { intensity: 0.4 }, main: { intensity: 1.2 } }
  },
  series: [
    {
      name: 'Network',
      type: 'lines3D',
      coordinateSystem: 'globe',
      blendMode: 'lighter',
      lineStyle: { width: 0.6, color: '#59c4ff', opacity: 0.25 },
      data: normal
    },
    {
      name: 'Reroute pressure (moderate, 1-3x)',
      type: 'lines3D',
      coordinateSystem: 'globe',
      blendMode: 'lighter',
      lineStyle: { width: 2.2, color: '#ffcc66', opacity: 0.85 },
      data: modPressure
    },
    {
      name: 'Reroute pressure (high, 3x+)',
      type: 'lines3D',
      coordinateSystem: 'globe',
      blendMode: 'lighter',
      lineStyle: { width: 4, color: '#ff8800', opacity: 0.9 },
      data: highPressure
    },
    {
      name: 'New route (previously unused)',
      type: 'lines3D',
      coordinateSystem: 'globe',
      blendMode: 'lighter',
      lineStyle: { width: 2.6, color: '#ffe27a', opacity: 0.9 },
      data: newRoute
    },
    {
      name: 'Cut',
      type: 'lines3D',
      coordinateSystem: 'globe',
      blendMode: 'lighter',
      lineStyle: { width: 4, color: '#ff3333', opacity: 1 },
      effect: { show: true, trailWidth: 3, trailLength: 0.3, trailOpacity: 1, constantSpeed: 5 },
      data: cut
    }
  ]
};

return { version: 2, option: option, notMerge: false };
